c3='''def greatest_rows(readings):
    best = None
    winners = []
    for i in range(len(readings)):
        total = 0
        for value in readings[i]:
            total += value
        if best is None or total > best:
            best = total
            winners = [i]
        elif total == best:
            winners.append(i)
    return best, winners'''
add('14:c',['B2.2.2','B2.3.2','B2.3.3'],'Construct greatest_rows(readings) in Python for a nonempty rectangular integer nested list. Return a tuple containing the largest row total and a list of every row index tied for it. Do not use sum or max; the task assesses accumulation and comparison.','One solution:\n'+c3,[(1,'Initializes best/winner state.'),(1,'Visits all rows.'),(1,'Initializes row total for eachrow.'),(1,'Accumulates all values in correctrow.'),(1,'Correct greater-total comparison.'),(1,'Updates best and replaces winnerlist on newbest.'),(1,'Appends ties without discarding earlier tiedrows.'),(1,'Returns greatest total andall correct indices.')],[24,25,26],status='B',new_command='Construct',code=c3,check='Executed unique best,tied rows,negative totals andsingle row.',test_code=c3+'\nassert greatest_rows([[3,4],[6,1],[2,2]])==(7,[0,1])\nassert greatest_rows([[-5,-1],[-2,-1]])==(-3,[1])\nassert greatest_rows([[4]])==(4,[0])')
